Expor uma API sem a devida proteção é um convite ao desastre. A maioria das violações não vem de ataques sofisticados, vem de APIs mal configuradas, tokens sem expiração e ausência de validação de escopo.

**OAuth2** é o padrão da indústria para autorização (o que você pode fazer). **OpenID Connect (OIDC)** é uma camada construída sobre OAuth2 que adiciona autenticação (quem você é). Entender a diferença é fundamental.

Antes do OAuth2, se um aplicativo precisava acessar seus e-mails, você dava sua senha pra ele. O OAuth2 permite que você autorize o acesso sem compartilhar sua senha, similar a dar uma chave específica de um quarto do hotel em vez da chave-mestra.

### O Fluxo Authorization Code com PKCE

Este é o fluxo mais seguro pra aplicações web. O usuário nunca compartilha sua senha com sua aplicação, mas sim com o servidor de identidade.

```javascript
// Implementacao do Authorization Code com PKCE (Node.js/Express)
const crypto = require('crypto');

function gerarPKCE() {
  const verifier = crypto.randomBytes(32).toString('base64url');
  const challenge = crypto
    .createHash('sha256')
    .update(verifier)
    .digest('base64url');
  return { verifier, challenge };
}

app.get('/auth/login', (req, res) => {
  const { verifier, challenge } = gerarPKCE();
  req.session.pkceVerifier = verifier;

  const params = new URLSearchParams({
    response_type: 'code',
    client_id: process.env.OAUTH_CLIENT_ID,
    redirect_uri: 'https://meuapp.com/auth/callback',
    scope: 'openid email profile',
    state: crypto.randomBytes(16).toString('hex'),
    code_challenge: challenge,
    code_challenge_method: 'S256'
  });

  res.redirect(`https://provedor.com/oauth/authorize?${params}`);
});

app.get('/auth/callback', async (req, res) => {
  const { code } = req.query;

  const resposta = await fetch('https://provedor.com/oauth/token', {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      grant_type: 'authorization_code',
      client_id: process.env.OAUTH_CLIENT_ID,
      client_secret: process.env.OAUTH_CLIENT_SECRET,
      code,
      redirect_uri: 'https://meuapp.com/auth/callback',
      code_verifier: req.session.pkceVerifier
    })
  });

  const { access_token, refresh_token } = await resposta.json();
  req.session.tokens = { access_token, refresh_token };
  res.redirect('/dashboard');
});
```

### JWT (JSON Web Tokens)

Tokens JWT têm três partes separadas por pontos: Header.Payload.Signature. São assinados, não criptografados por padrão. Qualquer um pode decodificar o payload, mas só o servidor pode criar uma assinatura válida. Sempre valide o emissor (`iss`), o público (`aud`) e a expiração (`exp`) no backend.

```javascript
async function autenticar(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader?.startsWith('Bearer ')) {
    return res.status(401).json({ erro: 'Token nao fornecido' });
  }

  const token = authHeader.split(' ')[1];

  try {
    const payload = jwt.verify(token, process.env.JWT_PUBLIC_KEY, {
      algorithms: ['RS256'],
      issuer: 'api.meuapp.com',
      audience: 'app.meuapp.com'
    });
    req.usuario = payload;
    next();
  } catch (erro) {
    if (erro.name === 'TokenExpiredError') {
      return res.status(401).json({ erro: 'Token expirado', codigo: 'TOKEN_EXPIRED' });
    }
    return res.status(401).json({ erro: 'Token invalido' });
  }
}
```

Nunca armazene tokens em localStorage, é vulnerável a XSS. Use httpOnly cookies, inacessíveis via JavaScript. E a autorização sempre no backend: verificar a role do usuário só no frontend é trivialmente contornável. Sempre HTTPS em todos os endpoints, rate limiting nos endpoints de auth pra prevenir brute force e CORS configurado pra domínios específicos, nunca `*` em produção.

